"""Build design-review metadata from a read-only source snapshot; writes docs only."""
from pathlib import Path
import json, re

ROOT = Path(__file__).resolve().parent
audit = json.loads((ROOT / 'source-inventory.json').read_text(encoding='utf-8'))
screens = []

def screen(key, route, title, section, layout, primary='', actions='', fields='', note='', more='', tabs='', source=None):
    r = next((r for r in audit['routes'] if r['id'] == route), None)
    files = (source or ([r['file']] if r else []))
    if r:
        files = list(dict.fromkeys(files + [f for f in r['sourceModules'] if '/features/' in f and not f.endswith('/api.ts')]))
    split = lambda x: [p.strip() for p in x.split('|') if p.strip()]
    obj = dict(key=key,route=route,title=title,section=section,layout=layout,primary=primary,actions=split(actions),fields=split(fields),note=note,more=split(more),tabs=split(tabs),files=files,authored=True)
    screens.append(obj)
    return obj

