# Every route remains discoverable. Unauthored routes use the shared screen pattern
# and retain a full source register; this is deliberately distinguished from a bespoke design.
for r in audit['routes']:
 if not any(s['route']==r['id'] for s in screens):
  excluded='legacy redirect' in r['reviewDisposition'].lower() or '/dev/' in r['id'] or r['id']==C+'invite-patient'
  section='Legacy & developer appendix' if excluded else ('Patient' if '/patient/' in r['id'] else 'Additional existing routes')
  o=screen('route-'+str(len(screens)),r['id'],r['title'],section,'source-pattern',note=r['reviewDisposition'])
  o['authored']=False

for s in screens:
 own=[c for c in audit['controls'] if c['file'] in s['files']]
 s['sourceControlIds']=[c['id'] for c in own]
 s['fieldSources']=[x for x in audit['fields'] if x['file'] in s['files']]
 s['configSources']=[x for x in audit['configs'] if x['file'] in s['files']]
 s['placements']=[]
 for label,place in [(s['primary'],'Primary action')]+[(a,'Visible section / toolbar') for a in s['actions']]+[(a,'Named secondary menu') for a in s['more']]:
  if not label:continue
  words=re.findall(r'[a-z]{4,}',label.lower())
  refs=[c['id'] for c in own if any(w in (c['label']+' '+str(c['events'])).lower() for w in words)]
  s['placements'].append(dict(label=label,placement=place,sourceRefs=refs,referenceMethod='Keyword candidate references; review original control/handler for exact semantics.'))

