lines=['# Route and option placement register','',f"Snapshot: 23 October 2026. {len(screens)} screen states across {audit['counts']['routes']} route files. Source control sites are declarations, not unique runtime buttons.",'','The prototype includes an Original controls panel for every screen. All 1,757 captured declaration sites remain in the searchable source register; this is not a claim that each is a distinct polished button. Auto-generated shared-pattern pages and unresolved dynamic labels are identified explicitly.','']
for s in screens:
 lines += ['## '+s['title']+' — '+s['key'],'',f"- Existing route: `{s['route']}`",f"- Design: {'Authored layout' if s['authored'] else 'Shared pattern / source review required'}",'- Context: '+s['note'],'','| Existing option / action family | Proposed placement |','| --- | --- |']
